'use strict';
const $=s=>document.querySelector(s),app=$('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['Addeena Safiya','Muhammad Harith','Nur Aisyah','Adam Rayyan','Siti Maryam','Umar Hakim'];
const initials=n=>n.split(' ').slice(0,2).map(s=>s[0]).join('');
const today=()=>new Date().toLocaleDateString('ms-MY',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Kuala_Lumpur'});
const key='halaqah-demo-v1';let storageOK=true;const seed=()=>({students:names.map((name,id)=>({id,name,book:id%2?'Al-Quran':'Iqra’ 4',page:13+id*3,attendance:'Belum ditanda'})),records:[],drafts:{},bills:[{id:'HQ-001',student:0,month:'Oktober 2026',amount:30,status:'Belum dibayar'},{id:'HQ-002',student:1,month:'Oktober 2026',amount:30,status:'Belum dibayar'},{id:'HQ-003',student:0,month:'September 2026',amount:30,status:'Dibayar'}],template:{focus:true,tajwid:true,note:true,statuses:['Lancar','Perlu bimbingan','Perlu ulang'],topics:['Ikhfa’','Izhar','Idgham','Iqlab','Mad asli','Qalqalah']},announcements:['Kelas mengaji & tajwid · Selasa dan Khamis, 5.00–6.30 petang.']});
let db;try{db=JSON.parse(localStorage.getItem(key))||seed()}catch{db=seed();storageOK=false}let role='teacher',view='class',selected=0,parentChild=0;let toastTimer;
function persist(){try{localStorage.setItem(key,JSON.stringify(db));return true}catch{storageOK=false;notify('Storan peranti tidak tersedia. Perubahan hanya kekal sepanjang sesi ini.');return false}}
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
const menus={teacher:[['class','▦','Kelas hari ini'],['attendance','✓','Kehadiran'],['reports','▤','Rekod pembelajaran']],parent:[['progress','◈','Perkembangan anak'],['fees','▤','Yuran & bayaran'],['announcements','♧','Pengumuman']],admin:[['overview','▦','Ringkasan'],['students','♙','Pelajar & kelas'],['billing','▤','Pengurusan yuran'],['template','⚙','Template pembelajaran']]};
function go(v){view=v;render();window.scrollTo({top:0,behavior:'smooth'})}
function nav(){const menu=menus[role];$('#navigation').innerHTML=menu.map(([id,icon,label])=>`<button class="nav-item ${view===id?'active':''}" data-view="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join('');$('#crumb').textContent=menu.find(m=>m[0]===view)?.[2]||'Halaqah';$('#identity').innerHTML=role==='teacher'?'Ustaz Ahmad<small>Tenaga pengajar</small>':role==='parent'?'Penjaga contoh<small>Ibu bapa / penjaga</small>':'Pentadbir surau<small>Pengurusan kelas</small>';$('#navigation').querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view))}
function heading(title,sub){return `<div class="page-title"><div><div class="eyebrow">MENGAJI & TAJWID</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="date">◷ &nbsp;${today()}</div></div>`}
function stats(items){return `<div class="stats">${items.map(([icon,n,label])=>`<div class="stat"><div class="stat-icon">${icon}</div><div><strong>${n}</strong><p>${label}</p></div></div>`).join('')}</div>`}
function last(id){return db.records.find(r=>r.student===id)}
function render(){nav();const renders={class:teacher,attendance:attendance,reports:reports,progress:parent,fees:fees,announcements:announcements,overview:overview,students:students,billing:billing,template:template};renders[view]();if(!storageOK)app.insertAdjacentHTML('afterbegin','<div class="notice">Storan peranti tidak tersedia. Data demo mungkin hilang selepas halaman ditutup.</div>')}
function teacher(){const done=db.students.filter(s=>last(s.id)?.date===today()).length;app.innerHTML=heading('Assalamualaikum, Ustaz Ahmad.','Satu bacaan, satu langkah ke hadapan.')+`<section class="welcome"><div><div class="eyebrow">RUANG UNTUK TUMBUH</div><h2>Temani setiap langkah<br>perjalanan ilmu mereka.</h2><p>Rekod ringkas hari ini, panduan bermakna untuk esok.</p></div><div class="welcome-badge">✧ &nbsp; Mengaji & Tajwid</div></section>`+stats([['♙',db.students.length,'Pelajar dalam kelas'],['✓',db.students.filter(s=>s.attendance==='Hadir'&&s.attendanceDate===today()).length,'Hadir hari ini'],['▤',`${done}/${db.students.length}`,'Rekod sesi hari ini']])+`<div class="section-head"><h2>Kelas hari ini</h2><span class="tiny">Selasa & Khamis · 5.00–6.30 petang</span></div><div class="workspace"><section class="card"><div class="card-top"><div><h3>Kumpulan An-Nur</h3><div class="class-meta">Mengaji & Tajwid · Bilik utama</div></div><span class="tag">${db.students.length} pelajar</span></div><input class="search" id="search" placeholder="Cari nama pelajar…" aria-label="Cari pelajar"><div class="student-list" id="student-list"></div></section><section class="card" id="record-panel"></section></div>`;studentList();$('#search').oninput=studentList;editor()}
function studentList(){const q=($('#search')?.value||'').toLowerCase();$('#student-list').innerHTML=db.students.filter(s=>s.name.toLowerCase().includes(q)).map(s=>`<button class="student ${s.id===selected?'selected':''}" data-student="${s.id}"><span class="avatar">${initials(s.name)}</span><span><span class="student-name">${esc(s.name)}</span><small>${esc(s.book)} · ${s.book==='Al-Quran'?'Ayat':'Muka surat'} ${s.page}</small><small><span class="dot"></span>${last(s.id)?.date===today()?'Rekod sesi disimpan':esc(s.attendance)}</small></span><span class="arrow">›</span></button>`).join('')||'<p class="empty">Tiada pelajar ditemui.</p>';$('#student-list').querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>{selected=+b.dataset.student;studentList();editor()})}
function chips(name,options,value,multiple=false){return `<div class="chips">${options.map(o=>`<label class="chip"><input type="${multiple?'checkbox':'radio'}" name="${name}" value="${esc(o)}" ${multiple?(value||[]).includes(o)?'checked':'':value===o?'checked':''}>${esc(o)}</label>`).join('')}</div>`}
function editor(){const s=db.students[selected],r=last(s.id),d=db.drafts[s.id]||{},t=db.template;$('#record-panel').innerHTML=`<div class="student-head"><span class="avatar">${initials(s.name)}</span><div><h2>${esc(s.name)}</h2><small>Kumpulan An-Nur</small></div><span class="tag">Rekod pembelajaran</span></div><div class="last-record"><b>↶ &nbsp; Sambung dari rekod terakhir</b><br>${esc(r?`${r.date} · ${r.book}, ${r.book==='Al-Quran'?'ayat':'muka surat'} ${r.page}`:`${s.book} · ${s.book==='Al-Quran'?'Ayat':'Muka surat'} ${s.page} · Rekod contoh`)}<br>${esc(r?r.summary:'Contoh panduan: ulang latihan panjang pendek sebelum sambung.')}</div><form id="record-form"><div class="form-section"><div class="number-label">01 &nbsp; BACAAN HARI INI</div><div class="form-row"><div class="field"><label for="book">Bahan bacaan</label><select name="book" id="book">${['Iqra’ 1','Iqra’ 2','Iqra’ 3','Iqra’ 4','Iqra’ 5','Iqra’ 6','Al-Quran'].map(b=>`<option ${(d.book||s.book)===b?'selected':''}>${b}</option>`).join('')}</select></div><div class="field"><label for="page" id="page-label">${(d.book||s.book)==='Al-Quran'?'Ayat':'Muka surat'}</label><div class="stepper"><button type="button" id="minus" aria-label="Kurangkan satu">−</button><input id="page" name="page" type="number" min="1" max="604" required value="${Number(d.page)||s.page}"><button type="button" id="plus" aria-label="Tambah satu">＋</button></div></div></div><div class="field" id="surah-field" ${(d.book||s.book)!=='Al-Quran'?'hidden':''}><label for="surah">Surah</label><select id="surah" name="surah">${['Al-Fatihah','Al-Baqarah','Ali Imran','An-Nisa’','Al-Ma’idah','Al-Ikhlas','Al-Falaq','An-Nas'].map(b=>`<option ${d.surah===b?'selected':''}>${b}</option>`).join('')}</select><small>Senarai surah terhad untuk demo.</small></div><div class="field"><span class="field-label">Tahap bacaan <span class="muted">· pilih satu</span></span>${chips('assessment',t.statuses,d.assessment)}</div>${t.focus?`<div class="field"><span class="field-label">Fokus pembaikan <span class="muted">· jika perlu</span></span>${chips('focus',['Makhraj','Panjang pendek','Kelancaran'],d.focus,true)}</div>`:''}<div class="field"><span class="field-label">Sesi seterusnya</span>${chips('next',['Sambung','Ulang'],d.next)}</div></div>${t.tajwid?`<hr class="divider"><label class="toggle-row"><span><b>02 &nbsp; Penilaian tajwid</b><small>Aktifkan jika dinilai dalam sesi ini</small></span><input id="tajwid-on" name="tajwidOn" type="checkbox" ${d.tajwidOn?'checked':''}></label><div id="tajwid-fields" ${d.tajwidOn?'':'hidden'}><div class="field"><label for="topic">Topik tajwid</label><select name="topic" id="topic"><option value="">Pilih topik</option>${t.topics.map(x=>`<option ${d.topic===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><span class="field-label">Tahap penguasaan</span>${chips('mastery',['Kenal hukum','Boleh aplikasikan','Perlu bimbingan'],d.mastery)}</div></div>`:''}${t.note?`<div class="field"><label for="note">Catatan tambahan <span class="muted">· pilihan</span></label><textarea rows="2" maxlength="500" name="note" id="note" placeholder="Tambah hanya jika perlu…">${esc(d.note||'')}</textarea></div>`:''}<div class="notice">✧ Pilihan cikgu akan disusun menjadi laporan untuk ibu bapa selepas disimpan.</div><div class="actions"><span class="save-status" id="save-status">${db.drafts[s.id]?'✓ Draf pada peranti ini':'Belum disimpan'}</span><button class="primary" type="submit">Simpan & pelajar seterusnya &nbsp; →</button></div></form>`;
const form=$('#record-form');function draft(){const f=new FormData(form);return {book:f.get('book'),page:+f.get('page'),surah:f.get('surah'),assessment:f.get('assessment'),focus:f.getAll('focus'),next:f.get('next'),tajwidOn:f.has('tajwidOn'),topic:f.get('topic'),mastery:f.get('mastery'),note:f.get('note')||''}}
form.oninput=()=>{db.drafts[s.id]=draft();const ok=persist();$('#save-status').textContent=ok?'✓ Draf disimpan pada peranti':'Draf dalam sesi ini sahaja'};$('#book').onchange=()=>{$('#surah-field').hidden=$('#book').value!=='Al-Quran';$('#page-label').textContent=$('#book').value==='Al-Quran'?'Ayat':'Muka surat'};['minus','plus'].forEach(id=>$('#'+id).onclick=()=>{const p=$('#page');p.value=Math.max(1,Math.min(604,(+p.value||1)+(id==='plus'?1:-1)));p.dispatchEvent(new Event('input',{bubbles:true}))});if($('#tajwid-on'))$('#tajwid-on').onchange=()=>$('#tajwid-fields').hidden=!$('#tajwid-on').checked;
form.onsubmit=e=>{e.preventDefault();const d=draft();if(!d.assessment||!d.next){notify('Pilih tahap bacaan dan tindakan sesi seterusnya.');return}if(d.tajwidOn&&(!d.topic||!d.mastery)){notify('Pilih topik dan tahap penguasaan tajwid.');return}const summary=`${s.name} membaca ${d.book}${d.book==='Al-Quran'?`, surah ${d.surah}, ayat`:', muka surat'} ${d.page}. ${d.assessment}.${d.focus.length?' Fokus latihan: '+d.focus.join(', ')+'.':''} ${d.next==='Ulang'?'Ulang bacaan ini':'Sambung bacaan'} pada sesi seterusnya.${d.tajwidOn?' Tajwid '+d.topic+': '+d.mastery+'.':''}${d.note?' '+d.note:''}`;db.records.unshift({...d,student:s.id,date:today(),time:new Date().toISOString(),summary});s.book=d.book;s.page=d.page;delete db.drafts[s.id];persist();selected=(selected+1)%db.students.length;teacher();notify('Rekod disimpan. Laporan ibu bapa dikemas kini dalam demo ini.')}}
function attendance(){app.innerHTML=heading('Kehadiran kelas','Tandakan kehadiran untuk sesi hari ini.')+`<section class="card"><div class="card-top"><h2>Kumpulan An-Nur</h2><span class="tag">${today()}</span></div>${db.students.map(s=>`<div class="attendance-row"><div><b>${esc(s.name)}</b><small>${esc(s.attendanceDate===today()?s.attendance:'Belum ditanda hari ini')}</small></div><div class="chips">${['Hadir','Tidak hadir','Berizin'].map(x=>`<button class="chip ${s.attendanceDate===today()&&s.attendance===x?'selected':''}" data-id="${s.id}" data-att="${x}">${x}</button>`).join('')}</div></div>`).join('')}</section>`;app.querySelectorAll('[data-att]').forEach(b=>b.onclick=()=>{const s=db.students[+b.dataset.id];s.attendance=b.dataset.att;s.attendanceDate=today();persist();attendance()})}
function recordTimeline(records){return records.length?`<div class="timeline">${records.map(r=>`<article><div class="tiny">${esc(r.date)} · ${esc(db.students[r.student].name)}</div><p>${esc(r.summary)}</p><span class="tag">${esc(r.assessment)}</span></article>`).join('')}</div>`:'<div class="empty">Belum ada rekod sesi.<br><small>Cuba simpan bacaan melalui paparan cikgu.</small></div>'}
function reports(){app.innerHTML=heading('Rekod pembelajaran','Setiap sesi yang disimpan, tersusun untuk rujukan.')+`<section class="card"><h2>Rekod mengaji & tajwid</h2>${recordTimeline(db.records)}</section>`}
function childSelect(){return `<select id="child" aria-label="Pilih anak">${db.students.filter(s=>[0,1].includes(s.id)).map(s=>`<option value="${s.id}" ${parentChild===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`}
function parent(){const s=db.students[parentChild],r=last(s.id);app.innerHTML=heading('Perjalanan ilmu anak anda.','Ikuti perkembangan, raikan setiap kemajuan kecil.')+`<div class="section-head"><h2>Anak di bawah jagaan</h2>${childSelect()}</div><div class="welcome"><div><div class="eyebrow">${esc(s.name)}</div><h2>${esc(s.book)}<br>${s.book==='Al-Quran'?'Ayat':'Muka surat'} ${s.page}</h2><p>${r?esc(r.assessment):'Rekod permulaan contoh · Belum dinilai dalam demo'}</p></div><span class="welcome-badge">✧ &nbsp; Teruskan usaha</span></div><div class="grid2"><section class="card"><h2>Perkembangan terkini</h2>${recordTimeline(db.records.filter(r=>r.student===parentChild))}</section><section class="card"><h2>Latihan & makluman</h2><div class="last-record"><b>Latihan seterusnya</b><br>${r?esc(`${r.next==='Ulang'?'Ulang':'Sambung'} ${r.book}, ${r.book==='Al-Quran'?'ayat':'muka surat'} ${r.page}. ${r.focus.join(', ')}`):'Latihan akan muncul selepas cikgu menyimpan rekod.'}</div><p class="subtitle">Kumpulan An-Nur · Ustaz Ahmad</p><p class="subtitle">${esc(db.announcements[0])}</p><button class="secondary" id="open-fees">Semak yuran →</button></section></div>`;$('#child').onchange=e=>{parentChild=+e.target.value;parent()};$('#open-fees').onclick=()=>go('fees')}
function fees(){const bills=db.bills.filter(b=>[0,1].includes(b.student));app.innerHTML=heading('Yuran & bayaran','Semak bil untuk semua anak di bawah jagaan.')+`<div class="notice">Demo bayaran sahaja. Tiada wang dicaj, QR bank atau gateway sebenar disambungkan.</div><section class="card">${bills.map(b=>`<div class="bill"><div><strong>${esc(db.students[b.student].name)}</strong><small>${esc(b.id)} · ${esc(b.month)}</small><small>${esc(b.status)}</small></div><div><strong>RM${b.amount.toFixed(2)}</strong>${b.status==='Belum dibayar'?`<button class="secondary" data-pay="${b.id}">Lihat bayaran</button>`:`<span class="tag">${esc(b.status)}</span>`}</div></div>`).join('')}</section><section id="payment-panel"></section>`;app.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>payment(b.dataset.pay))}
function payment(id){const b=db.bills.find(b=>b.id===id);$('#payment-panel').innerHTML=`<div class="card" style="margin-top:20px"><h2>Bayaran ${esc(b.id)}</h2><div class="amount">RM${b.amount.toFixed(2)}</div><p class="subtitle">Dalam versi sebenar, QR institusi atau pautan gateway akan dipaparkan di sini.</p><div class="notice">Untuk menguji aliran semakan, hantar permohonan demo. Ia tidak membuktikan bayaran sebenar.</div><button class="primary" id="submit-payment">Simulasi hantar untuk semakan admin</button></div>`;$('#submit-payment').onclick=()=>{b.status='Menunggu semakan';persist();fees();notify('Permohonan demo dihantar. Tukar ke paparan admin untuk sahkan.')}}
function announcements(){app.innerHTML=heading('Pengumuman','Makluman daripada pengurusan kelas.')+db.announcements.map(x=>`<section class="card"><span class="tag">Pengurusan surau</span><p>${esc(x)}</p></section>`).join('')}
function overview(){const unpaid=db.bills.filter(b=>b.status!=='Dibayar').reduce((n,b)=>n+b.amount,0);app.innerHTML=heading('Ruang pengurusan.','Pandangan ringkas operasi kelas mengaji & tajwid.')+stats([['♙',db.students.length,'Pelajar berdaftar'],['▤',db.records.length,'Rekod pembelajaran'],['◷',`RM${unpaid}`,'Yuran belum disahkan']])+`<div class="grid2"><section class="card"><h2>Aktiviti pembelajaran</h2>${recordTimeline(db.records.slice(0,3))}</section><section class="card"><h2>Pengurusan kelas</h2><div class="last-record"><b>Kumpulan An-Nur</b><br>Ustaz Ahmad · ${db.students.length} pelajar<br>Selasa & Khamis · 5.00–6.30 petang</div><p class="subtitle">Template pembelajaran boleh disesuaikan tanpa mengubah rekod lama.</p><button class="secondary" id="edit-template">Sesuaikan template →</button></section></div>`;$('#edit-template').onclick=()=>go('template')}
function students(){app.innerHTML=heading('Pelajar & kelas','Kumpulan An-Nur · Ustaz Ahmad')+`<section class="card"><div class="card-top"><h2>Senarai pelajar</h2><span class="tag">Data contoh</span></div><div class="table-wrap"><table><thead><tr><th>PELAJAR</th><th>BACAAN TERAKHIR</th><th>KEHADIRAN TERAKHIR</th></tr></thead><tbody>${db.students.map(s=>`<tr><td><b>${esc(s.name)}</b></td><td>${esc(s.book)} · ${s.page}</td><td>${esc(s.attendance)}</td></tr>`).join('')}</tbody></table></div><div class="notice">Pendaftaran pelajar, penugasan cikgu dan pengurusan banyak kelas akan disambungkan selepas struktur pilot disemak.</div></section>`}
function billing(){app.innerHTML=heading('Pengurusan yuran','Uji aliran bil bulanan dan pengesahan bayaran.')+`<div class="section-head"><h2>Bil kelas</h2><button class="primary" id="generate">＋ Jana bil bulan ini</button></div><div class="notice">Penjanaan bil manual untuk demo. Jadual automatik, email reminder dan resit rasmi belum diaktifkan.</div><section class="card"><div class="table-wrap"><table><thead><tr><th>BIL / PELAJAR</th><th>BULAN</th><th>JUMLAH</th><th>STATUS</th><th>TINDAKAN</th></tr></thead><tbody>${db.bills.map(b=>`<tr><td><b>${esc(b.id)}</b><small>${esc(db.students[b.student].name)}</small></td><td>${esc(b.month)}</td><td>RM${b.amount.toFixed(2)}</td><td><span class="tag">${esc(b.status)}</span></td><td>${b.status==='Menunggu semakan'?`<button class="secondary" data-confirm="${esc(b.id)}">Sahkan demo</button>`:'—'}</td></tr>`).join('')}</tbody></table></div></section>`;$('#generate').onclick=()=>{const month=new Date().toLocaleDateString('ms-MY',{month:'long',year:'numeric',timeZone:'Asia/Kuala_Lumpur'});let count=0;db.students.forEach(s=>{if(!db.bills.some(b=>b.student===s.id&&b.month===month)){db.bills.push({id:`HQ-${Date.now()}-${s.id}`,student:s.id,month,amount:30,status:'Belum dibayar'});count++}});persist();billing();notify(count?`${count} bil contoh dijana. Tiada email dihantar.`:'Bil bulan ini sudah tersedia; tiada bil pendua dijana.')};app.querySelectorAll('[data-confirm]').forEach(b=>b.onclick=()=>{db.bills.find(x=>x.id===b.dataset.confirm).status='Dibayar';persist();billing();notify('Bayaran demo disahkan.')})}
function template(){app.innerHTML=heading('Template pembelajaran','Pentadbiran tetapkan borang. Cikgu hanya pilih dan simpan.')+`<div class="grid2"><section class="card"><h2>Medan dalam borang cikgu</h2><p class="subtitle">Mengaji ialah rekod utama. Bahagian tambahan boleh disembunyikan.</p><form id="template-form">${[['focus','Fokus pembaikan'],['tajwid','Penilaian tajwid'],['note','Catatan tambahan (pilihan)']].map(([k,label])=>`<label class="template-row"><input type="checkbox" name="${k}" ${db.template[k]?'checked':''}>${label}</label>`).join('')}<div class="field"><label for="statuses">Pilihan tahap bacaan · satu setiap baris</label><textarea rows="4" id="statuses" name="statuses" maxlength="300">${esc(db.template.statuses.join('\n'))}</textarea></div><div class="field"><label for="topics">Topik tajwid · satu setiap baris</label><textarea rows="6" id="topics" name="topics" maxlength="600">${esc(db.template.topics.join('\n'))}</textarea></div><button class="primary">Simpan template</button></form></section><section class="card"><h2>Ringkas untuk cikgu</h2><div class="last-record"><b>01 · Bacaan hari ini</b><br>Bahan bacaan dan muka surat / ayat<br>Pilih tahap bacaan<br>Pilih sambung atau ulang</div><div class="last-record"><b>02 · Tajwid, jika dinilai</b><br>Pilih topik dan tahap penguasaan</div><p class="subtitle">Perubahan digunakan untuk borang baharu. Laporan lama mengekalkan maklumat yang telah disimpan.</p><div class="notice">Tambah jenis medan baharu dan tetapan mengikut kelas dirancang untuk fasa seterusnya. Demo ini menyediakan tetapan asas dahulu.</div></section></div>`;$('#template-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),lines=k=>[...new Set(f.get(k).split('\n').map(x=>x.trim()).filter(Boolean))];if(!lines('statuses').length||!lines('topics').length){notify('Sediakan sekurang-kurangnya satu tahap dan satu topik.');return}db.template={focus:f.has('focus'),tajwid:f.has('tajwid'),note:f.has('note'),statuses:lines('statuses'),topics:lines('topics')};persist();notify('Template dikemas kini. Cuba melalui paparan cikgu.')}}
$('#role').onchange=e=>{role=e.target.value;view=menus[role][0][0];render()};let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install').hidden=true}};if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});render();
